Below is a minimal, self‑contained Go program that implements a simple in‑memory task manager with a REST API.  
It uses only the Go standard library (no external dependencies) and supports the four operations you asked for:

| HTTP Method | Path               | Action                              |
|-------------|--------------------|-------------------------------------|
| `GET`       | `/{{p:entity}}`           | List all {{p:entity}}                      |
| `GET`       | `/{{p:entity}}/{id}`      | Get a single task by its numeric ID |
| `POST`      | `/{{p:entity}}`           | Create a new task (JSON body)       |
| `DELETE`    | `/{{p:entity}}/{id}`      | Delete a task by ID                 |

```go
// main.go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
)

// Task represents a single to‑do item.
type Task struct {
	ID          int    `json:"id"`          // unique identifier (assigned by server)
	Title       string `json:"title"`       // short description
	Description string `json:"description"` // optional longer description
	Done        bool   `json:"done"`        // completion flag
}

// store holds all {{p:entity}} in memory and protects them with a mutex.
type store struct {
	sync.Mutex
	{{p:entity}} map[int]*Task
	next  int // next ID to assign
}

func newStore() *store {
	return &store{
		{{p:entity}}: make(map[int]*Task),
		next:  1,
	}
}

// ---------- Handlers ----------

// list{{p:entity:title}} returns all {{p:entity}} as JSON.
func (s *store) list{{p:entity:title}}(w http.ResponseWriter, r *http.Request) {
	s.Lock()
	defer s.Unlock()

	// Collect {{p:entity}} into a slice for deterministic ordering.
	list := make([]*Task, 0, len(s.{{p:entity}}))
	for _, t := range s.{{p:entity}} {
		list = append(list, t)
	}

	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(list); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
	}
}

// getTask returns a single task identified by /{{p:entity}}/{id}.
func (s *store) getTask(w http.ResponseWriter, r *http.Request) {
	id, ok := s.extractID(w, r)
	if !ok {
		return // error already written
	}

	s.Lock()
	defer s.Unlock()

	task, exists := s.{{p:entity}}[id]
	if !exists {
		http.Error(w, fmt.Sprintf("task %d not found", id), http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(task); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
	}
}

// createTask reads a JSON body, assigns a new ID, stores the task, and returns it.
func (s *store) createTask(w http.ResponseWriter, r *http.Request) {
	var payload struct {
		Title       string `json:"title"`
		Description string `json:"description,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
		http.Error(w, "invalid JSON body", http.StatusBadRequest)
		return
	}
	if strings.TrimSpace(payload.Title) == "" {
		http.Error(w, "title is required", http.StatusBadRequest)
		return
	}

	s.Lock()
	defer s.Unlock()

	newTask := &Task{
		ID:          s.next,
		Title:       payload.Title,
		Description: payload.Description,
		Done:        false,
	}
	s.{{p:entity}}[newTask.ID] = newTask
	s.next++

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	if err := json.NewEncoder(w).Encode(newTask); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
	}
}

// deleteTask removes a task by ID.
func (s *store) deleteTask(w http.ResponseWriter, r *http.Request) {
	id, ok := s.extractID(w, r)
	if !ok {
		return // error already written
	}

	s.Lock()
	defer s.Unlock()

	if _, exists := s.{{p:entity}}[id]; !exists {
		http.Error(w, fmt.Sprintf("task %d not found", id), http.StatusNotFound)
		return
	}
	delete(s.{{p:entity}}, id)

	w.WriteHeader(http.StatusNoContent) // 204 No Content
}

// extractID parses the numeric ID from the URL path /{{p:entity}}/{id}.
func (s *store) extractID(w http.ResponseWriter, r *http.Request) (int, bool) {
	parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
	if len(parts) != 2 {
		http.Error(w, "invalid URL, expected /{{p:entity}}/{id}", http.StatusBadRequest)
		return 0, false
	}
	id, err := strconv.Atoi(parts[1])
	if err != nil {
		http.Error(w, "id must be an integer", http.StatusBadRequest)
		return 0, false
	}
	return id, true
}

// ---------- Router ----------
func (s *store) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// Only paths that start with /{{p:entity}} are handled here.
	if !strings.HasPrefix(r.URL.Path, "/{{p:entity}}") {
		http.NotFound(w, r)
		return
	}

	switch r.Method {
	case http.MethodGet:
		// /{{p:entity}}            -> list
		// /{{p:entity}}/{id}       -> get single
		if r.URL.Path == "/{{p:entity}}" {
			s.list{{p:entity:title}}(w, r)
		} else {
			s.getTask(w, r)
		}
	case http.MethodPost:
		if r.URL.Path != "/{{p:entity}}" {
			http.Error(w, "POST only allowed on /{{p:entity}}", http.StatusBadRequest)
			return
		}
		s.createTask(w, r)
	case http.MethodDelete:
		s.deleteTask(w, r)
	default:
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
	}
}

// ---------- main ----------
func main() {
	s := newStore()
	fmt.Println("Task API listening on http://localhost:8080")
	log.Fatal(http.ListenAndServe(":8080", s))
}
```

### How it works
1. **In‑memory storage** – `store` holds a map of `Task` pointers protected by a `sync.Mutex`. The `next` field auto‑increments IDs.
2. **Routing** – The `store` implements `http.Handler`. All `/{{p:entity}}*` URLs are routed here, and the HTTP method decides which handler runs.
3. **Endpoints**
   * `GET /{{p:entity}}` – returns a JSON array of all {{p:entity}}.
   * `GET /{{p:entity}}/{id}` – returns the task with that numeric ID or `{{int:323:485}}`.
   * `POST /{{p:entity}}` – expects JSON `{ "title": "...", "description": "..." }`, creates a task, returns `{{int:160:242}}` with the newly created task (including its generated `id`).
   * `DELETE /{{p:entity}}/{id}` – removes the task, returns `{{int:163:245}} No Content` on success.
4. **Concurrency** – All modifications/read‑operations lock the store, guaranteeing safe concurrent access.

### Running the program
```bash
# Save the file as main.go
go run main.go
```
The server will listen on `localhost:8080`. You can test it with `curl`:

```bash
# Create a task
curl -X POST -d '{"title":"Buy milk"}' -H "Content-Type: application/json" http://localhost:8080/{{p:entity}}

# List {{p:entity}}
curl http://localhost:8080/{{p:entity}}

# Get task 1
curl http://localhost:8080/{{p:entity}}/1

# Delete task 1
curl -X DELETE http://localhost:8080/{{p:entity}}/1
```

Because the data lives only in memory, restarting the program clears all {{p:entity}}—perfect for a simple demo or prototyping scenario.

Below is a complete **`main_test.go`** file you can place alongside the `main.go` implementation.  
It uses only the Go standard library (`testing`, `net/http/httptest`, `encoding/json`, etc.) and covers the four core operations:

| Test | What it verifies |
|------|-------------------|
| **TestCreateTask** | `POST /{{p:entity}}` creates a task, returns `{{int:160:242}}`, and the response body contains the generated `id`. |
| **TestList{{p:entity:title}}** | After creating a few {{p:entity}}, `GET /{{p:entity}}` returns a JSON array containing all of them. |
| **TestGetTask** | `GET /{{p:entity}}/{id}` returns the correct task and a `{{int:160:240}}` status; requesting a non‑existent ID yields `{{int:323:485}}`. |
| **TestDeleteTask** | `DELETE /{{p:entity}}/{id}` removes a task (returns `{{int:163:245}}`), and a subsequent `GET` for that ID returns `{{int:323:485}}`. |
| **TestInvalidMethods & URLs** | Ensures unsupported methods/paths return the proper error codes (`{{int:324:486}}`, `{{int:323:485}}`, etc.). |

```go
// main_test.go
package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"testing"
)

// helper that creates a new in‑memory store and wraps it with httptest.Server
func newTestServer() (*httptest.Server, *store) {
	s := newStore()
	ts := httptest.NewServer(s)
	return ts, s
}

// helper to POST a task and return the created Task struct
func postTask(t *testing.T, client *http.Client, baseURL, title, description string) Task {
	payload := map[string]string{
		"title":       title,
		"description": description,
	}
	body, _ := json.Marshal(payload)

	req, err := http.NewRequest(http.MethodPost, baseURL+"/{{p:entity}}", bytes.NewReader(body))
	if err != nil {
		t.Fatalf("creating POST request: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")

	resp, err := client.Do(req)
	if err != nil {
		t.Fatalf("POST request failed: %v", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusCreated {
		t.Fatalf("expected status 201 Created, got %d", resp.StatusCode)
	}

	var created Task
	if err := json.NewDecoder(resp.Body).Decode(&created); err != nil {
		t.Fatalf("decoding response: %v", err)
	}
	if created.Title != title {
		t.Errorf("expected title %q, got %q", title, created.Title)
	}
	return created
}

// ---------- Tests ----------

func TestCreateTask(t *testing.T) {
	ts, _ := newTestServer()
	defer ts.Close()

	client := ts.Client()
	created := postTask(t, client, ts.URL, "Write unit tests", "Add coverage for all handlers")

	if created.ID == 0 {
		t.Errorf("expected non‑zero ID after creation")
	}
	if created.Done {
		t.Errorf("new {{p:entity}} should default to Done == false")
	}
}

func TestList{{p:entity:title}}(t *testing.T) {
	ts, _ := newTestServer()
	defer ts.Close()
	client := ts.Client()

	// Create three {{p:entity}}
	expected := []Task{
		postTask(t, client, ts.URL, "Task A", ""),
		postTask(t, client, ts.URL, "Task B", ""),
		postTask(t, client, ts.URL, "Task C", ""),
	}

	// GET /{{p:entity}}
	resp, err := client.Get(ts.URL + "/{{p:entity}}")
	if err != nil {
		t.Fatalf("GET /{{p:entity}} failed: %v", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		t.Fatalf("expected 200 OK, got %d", resp.StatusCode)
	}

	var listed []Task
	if err := json.NewDecoder(resp.Body).Decode(&listed); err != nil {
		t.Fatalf("decoding list response: %v", err)
	}

	if len(listed) != len(expected) {
		t.Fatalf("expected %d {{p:entity}}, got %d", len(expected), len(listed))
	}

	// Simple existence check – ensure each expected ID appears in the result.
	expectedIDs := make(map[int]bool)
	for _, tsk := range expected {
		expectedIDs[tsk.ID] = true
	}
	for _, tsk := range listed {
		if !expectedIDs[tsk.ID] {
			t.Errorf("unexpected task ID %d in list", tsk.ID)
		}
	}
}

func TestGetTask(t *testing.T) {
	ts, _ := newTestServer()
	defer ts.Close()
	client := ts.Client()

	created := postTask(t, client, ts.URL, "Fetch me", "")

	// GET existing task
	resp, err := client.Get(ts.URL + "/{{p:entity}}/" + strconv.Itoa(created.ID))
	if err != nil {
		t.Fatalf("GET existing task failed: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("expected 200 OK for existing task, got %d", resp.StatusCode)
	}
	var fetched Task
	if err := json.NewDecoder(resp.Body).Decode(&fetched); err != nil {
		t.Fatalf("decoding fetched task: %v", err)
	}
	if fetched.ID != created.ID || fetched.Title != created.Title {
		t.Errorf("fetched task does not match created one")
	}

	// GET non‑existent task
	resp2, err := client.Get(ts.URL + "/{{p:entity}}/9999")
	if err != nil {
		t.Fatalf("GET non‑existent task request failed: %v", err)
	}
	defer resp2.Body.Close()
	if resp2.StatusCode != http.StatusNotFound {
		t.Fatalf("expected 404 Not Found for missing task, got %d", resp2.StatusCode)
	}
}

func TestDeleteTask(t *testing.T) {
	ts, _ := newTestServer()
	defer ts.Close()
	client := ts.Client()

	created := postTask(t, client, ts.URL, "Will be deleted", "")

	// DELETE the task
	req, err := http.NewRequest(http.MethodDelete, ts.URL+"/{{p:entity}}/"+strconv.Itoa(created.ID), nil)
	if err != nil {
		t.Fatalf("creating DELETE request: %v", err)
	}
	resp, err := client.Do(req)
	if err != nil {
		t.Fatalf("DELETE request failed: %v", err)
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusNoContent {
		t.Fatalf("expected 204 No Content on delete, got %d", resp.StatusCode)
	}

	// Verify it is gone
	resp2, err := client.Get(ts.URL + "/{{p:entity}}/" + strconv.Itoa(created.ID))
	if err != nil {
		t.Fatalf("GET after delete failed: %v", err)
	}
	resp2.Body.Close()
	if resp2.StatusCode != http.StatusNotFound {
		t.Fatalf("expected 404 after deleting task, got %d", resp2.StatusCode)
	}
}

// Optional: ensure unsupported methods/paths return proper errors.
func TestInvalidMethodsAndPaths(t *testing.T) {
	ts, _ := newTestServer()
	defer ts.Close()
	client := ts.Client()

	// POST to /{{p:entity}}/{id} (should be rejected)
	req, _ := http.NewRequest(http.MethodPost, ts.URL+"/{{p:entity}}/1", nil)
	resp, err := client.Do(req)
	if err != nil {
		t.Fatalf("POST to /{{p:entity}}/{id} failed: %v", err)
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusBadRequest {
		t.Errorf("expected 400 Bad Request for POST /{{p:entity}}/{id}, got %d", resp.StatusCode)
	}

	// Unknown path
	resp2, err := client.Get(ts.URL + "/unknown")
	if err != nil {
		t.Fatalf("GET unknown path failed: %v", err)
	}
	resp2.Body.Close()
	if resp2.StatusCode != http.StatusNotFound {
		t.Errorf("expected 404 Not Found for unknown path, got %d", resp2.StatusCode)
	}
}
```

### How to run the tests

1. **Save the file** next to `main.go` (same package `main`).  
2. Open a terminal in that directory and execute:

```bash
go test -v
```

You should see output similar to:

```
=== RUN   TestCreateTask
--- PASS: TestCreateTask (0.00s)
=== RUN   TestList{{p:entity:title}}
--- PASS: TestList{{p:entity:title}} (0.00s)
=== RUN   TestGetTask
--- PASS: TestGetTask (0.00s)
=== RUN   TestDeleteTask
--- PASS: TestDeleteTask (0.00s)
=== RUN   TestInvalidMethodsAndPaths
--- PASS: TestInvalidMethodsAndPaths (0.00s)
PASS
ok  	<module‑path>	0.XXXs
```

All core API functionalities are now covered by unit tests, giving you confidence that the in‑memory task manager behaves as expected. Feel free to add more edge‑case tests (e.g., malformed JSON, huge payloads, concurrent requests) as your project evolves.
